    // Initialize the circulator to start at the given node
    OuterFaceCirculator circulator = new OuterFaceCirculator(start);

    // Iterate over the circulator until we find a node that satisfies the predicate or reach the stop node
    while (circulator.hasNext() && !predicate.test(circulator.next())) {
        // If we reach the stop node, return the circulator
        if (circulator.next() == stop) {
            return circulator;
        }
    }

    // If we didn't find a node that satisfies the predicate, return the circulator
    return circulator;
}

